import { Effect } from "effect"

export interface Shipment {
  readonly trackingNumber: string
  readonly destination: string
  readonly parcelCount: number
}

export interface ManifestStore {
  readonly pending: (
    warehouse: string
  ) => Effect.Effect<ReadonlyArray<Shipment>, Error>
  readonly save: (
    warehouse: string,
    contents: string
  ) => Effect.Effect<string, Error>
}

const renderManifest = (
  warehouse: string,
  shipments: ReadonlyArray<Shipment>
): string => {
  const rows = shipments.map((shipment) =>
    [shipment.trackingNumber, shipment.destination, shipment.parcelCount].join(",")
  )
  return [`Warehouse: ${warehouse}`, ...rows].join("\n")
}

export const createDispatchManifest = (
  store: ManifestStore,
  warehouse: string
) =>
  Effect.gen(function*() {
    const contents = yield* store.pending(warehouse).pipe(
      Effect.map((shipments) => renderManifest(warehouse, shipments))
    )
    const location = yield* store.save(warehouse, contents)
    yield* Effect.logInfo("Dispatch manifest saved", { warehouse, location })
    return { warehouse, location }
  })
